package com.carenexus.api.storage;

import java.io.InputStream;
import java.net.URI;
import java.time.Duration;
import java.util.Optional;

/**
 * Provider seam for stored files (documents, data exports, receipts). Selected by
 * {@code carenexus.storage.provider}: {@code local} (default, a directory on this machine) or a real object store
 * once an adapter is added to {@code StorageConfig}.
 *
 * Keys are generated by the caller as {@code "<area>/<yyyy>/<mm>/<uuid>"} (lower-case letters, digits,
 * {@code . _ -} and {@code /} separators); a client-supplied file name is never part of a key. The storage does not
 * authorise anything: every caller authorises and audits the upload or download before it touches the storage, and
 * scans uploads with {@link FileScanner} first.
 */
public interface FileStorage {

    /** Lower-case provider id, for example {@code local}, {@code s3}. */
    String providerName();

    /**
     * Stores the content under {@code key}, replacing a file that is already there. The stream is read to its end
     * and not closed.
     *
     * @param contentType type recorded with the object where the provider supports it (the local directory does not)
     * @param size        number of bytes the caller expects, or a negative value when unknown; a different number
     *                    of bytes read fails the upload and stores nothing
     * @return the key, the number of bytes stored and their SHA-256 (lower-case hex)
     * @throws StorageException when the key is invalid or the content cannot be stored
     */
    StoredFile put(String key, String contentType, InputStream content, long size);

    /**
     * Opens the stored content. The caller closes the stream.
     *
     * @throws StoredFileNotFoundException when nothing is stored under the key
     * @throws StorageException            when the key is invalid or the content cannot be read
     */
    InputStream open(String key);

    /** Deletes the stored content. Deleting a key that does not exist is not an error. */
    void delete(String key);

    /**
     * A time-limited direct download URL, when the provider has them. Empty for the local storage: downloads always
     * stream through the API, which authorises and audits them.
     */
    Optional<URI> signedUrl(String key, Duration ttl);
}
